-- Phase O hardening: critical/high policy denials automatically open durable incidents.
create or replace function public.security_authorize_action(p_idempotency_key text,p_actor_id uuid,p_agent_key text,p_action text,p_resource_type text default null,p_resource_id text default null,p_task_id uuid default null,p_run_id uuid default null,p_context jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare existing public.security_requests; policy_row public.security_policies; decision text := 'deny'; reason text := 'No active security policy matched the requested action'; matched uuid[] := '{}'::uuid[]; req public.security_requests; event_row public.security_events; event_severity text := 'medium'; begin select * into existing from public.security_requests where idempotency_key=p_idempotency_key limit 1; if found then return jsonb_build_object('allowed',existing.decision='allow','requires_approval',existing.decision='approval_required','decision',existing.decision,'reason',existing.reason,'request_id',existing.id,'policy_ids',existing.matched_policy_ids); end if; select * into policy_row from public.security_policies where status='active' and p_action ~ action_pattern and coalesce(p_resource_type,'') ~ resource_type_pattern order by priority desc,version desc,created_at desc limit 1; if found then matched:=array[policy_row.id]; if policy_row.effect='allow' then decision:='allow'; reason:=policy_row.description; event_severity:='low'; elsif policy_row.effect='approval' then decision:='approval_required'; reason:=policy_row.description; event_severity:=case when policy_row.severity in ('high','critical') then policy_row.severity else 'medium' end; else decision:='deny'; reason:=policy_row.description; event_severity:=policy_row.severity; end if; end if; insert into public.security_requests(idempotency_key,actor_id,agent_key,action,resource_type,resource_id,task_id,run_id,context,decision,reason,matched_policy_ids,expires_at) values(p_idempotency_key,p_actor_id,p_agent_key,p_action,p_resource_type,p_resource_id,p_task_id,p_run_id,coalesce(p_context,'{}'::jsonb),decision,coalesce(nullif(reason,''),'Security policy decision'),matched,case when decision='approval_required' then now()+interval '15 minutes' else null end) returning * into req; insert into public.security_events(event_type,severity,actor_id,agent_key,action,resource_type,resource_id,task_id,run_id,request_id,message,metadata) values('policy.decision',event_severity,p_actor_id,p_agent_key,p_action,p_resource_type,p_resource_id,p_task_id,p_run_id,req.id,'Security policy evaluated',jsonb_build_object('decision',decision,'policy_ids',matched)) returning * into event_row; if decision='deny' and event_severity in ('high','critical') then perform public.create_security_incident(concat('policy-deny:',req.id::text),'policy_violation',event_severity,concat('Security policy denied ',p_action),coalesce(reason,'Security policy denial'),event_row.id,p_actor_id,p_agent_key,jsonb_build_object('action',p_action,'resource_type',p_resource_type,'resource_id',p_resource_id,'request_id',req.id)); end if; return jsonb_build_object('allowed',decision='allow','requires_approval',decision='approval_required','decision',decision,'reason',reason,'request_id',req.id,'policy_ids',matched); end; $$;
revoke all on function public.security_authorize_action(text,uuid,text,text,text,text,uuid,uuid,jsonb) from public,anon,authenticated; grant execute on function public.security_authorize_action(text,uuid,text,text,text,text,uuid,uuid,jsonb) to service_role;
